"""Author PRE_A1-U08 only; preserve earlier packages and lexical keys."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/PRE_A1.plan.json').read_text())['level']
plan=level['units'][7]
W={}
for source in [OUT/f'PRE_A1-U{n:02}.v1.json' for n in range(7,1,-1)]+[KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='PRE_A1.U08.UNDERSTAND';A='PRE_A1.U08.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='PRE_A1',unit_id=plan['id'],description=d,duration_minutes=6,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — французский с нуля',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def grammar(t):
 t['skill']='grammar'
 return t

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
addword('grand','fr:grand:large-object','grand','большой (о размере вещи)','гра́(н)',ex('Un grand sac.','Большая сумка.','э(н) гра(н) са́к'),1,[rev('grand-meaning',fr('Grand','гра́(н)'),['Маленький','Большой','Красный'],1,'Это большой размер вещи.','Правильный смысл — большой, а не маленький или красный.'),rev('grand-use',ru('Нужна книга большого размера. В какой записи размер указан прямо?'),[fr('Un petit livre','э(н) пёти ли́вр'),fr('Un livre rouge','э(н) ливр ру́ж'),fr('Un grand livre','э(н) гра(н) ли́вр')],2,'В записи прямо указан большой размер книги.','Нужен большой размер; маленький не подходит, а красный цвет размер не сообщает.')])
addword('petit','fr:petit:small-object','petit','маленький (о размере вещи)','пёти́',ex('Un petit sac.','Маленькая сумка.','э(н) пёти са́к'),1,[rev('petit-meaning',fr('Petit','пёти́'),['Маленький','Синий','Большой'],0,'Это маленький размер вещи.','Правильный смысл — маленький; цвет и большой размер означают другое.'),rev('petit-use',ru('Нужна маленькая книга. В какой записи прямо указан такой размер?'),[fr('Un grand livre','э(н) гра(н) ли́вр'),fr('Un petit livre','э(н) пёти ли́вр'),fr('Un livre bleu','э(н) ливр блё́')],1,'Выбрано название книги с маленьким размером.','Нужна маленькая книга; большой размер не подходит, а цвет не уточняет размер.')])
addword('long','fr:long:long-length','long','длинный','ло́(н)',ex('Un stylo long.','Длинная ручка.','э(н) стило ло́(н)'),2,[rev('long-meaning',fr('Long','ло́(н)'),['Короткий','Большой','Длинный'],2,'Слово сообщает большую длину.','Это именно длинный, а не короткий или общее обозначение большого размера.'),rev('long-use',ru('В условии нужна длинная ручка. Какая запись прямо сообщает её длину?'),[fr('Un stylo long','э(н) стило ло́(н)'),fr('Un stylo court','э(н) стило ку́р'),fr('Un petit stylo','э(н) пёти стило́')],0,'В записи прямо указана требуемая длина.','Нужна запись «длинная ручка»; короткая не подходит, а маленький размер сам по себе не задаёт длину.')])
addword('court','fr:court:short-length','court','короткий','ку́р',ex('Un stylo court.','Короткая ручка.','э(н) стило ку́р'),2,[rev('court-meaning',fr('Court','ку́р'),['Короткий','Длинный','Маленький'],0,'Слово сообщает короткую длину.','Это короткий, а не длинный или общее обозначение маленького размера.'),rev('court-use',ru('Нужна короткая ручка. В какой записи длина названа прямо?'),[fr('Un stylo long','э(н) стило ло́(н)'),fr('Un grand stylo','э(н) гра(н) стило́'),fr('Un stylo court','э(н) стило ку́р')],2,'Выбрана запись с короткой длиной ручки.','Нужен признак короткой длины; большой размер не заменяет его, а длинная ручка не подходит.')])
addword('nouveau','fr:nouveau:new-object','nouveau','новый (о вещи)','нуво́',ex('Un nouveau sac.','Новая сумка.','э(н) нуво са́к'),3,[rev('nouveau-meaning',fr('Nouveau','нуво́'),['Старый','Новый','Красный'],1,'Здесь назван новый предмет.','Правильное значение — новый; старый и красный сообщают другие признаки.'),rev('nouveau-use',ru('В подписи нужно прямо указать, что ручка новая. Какую запись выбрать?'),[fr('Un stylo rouge','э(н) стило ру́ж'),fr('Un nouveau stylo','э(н) нуво стило́'),fr('Un vieux stylo','э(н) вьё стило́')],1,'В записи прямо указано, что ручка новая.','Нужен признак «новая»; старый предмет не подходит, а цвет не сообщает, новый он или старый.')])
addword('vieux','fr:vieux:old-object','vieux','старый (о вещи)','вьё́',ex('Un vieux sac.','Старая сумка.','э(н) вьё са́к'),3,[rev('vieux-meaning',fr('Vieux','вьё́'),['Синий','Новый','Старый'],2,'В этом контексте речь о старой вещи.','Правильный смысл — старый; не подменяйте его цветом или признаком нового предмета.'),rev('vieux-use',ru('В подписи нужно прямо указать, что ручка старая. Какую запись выбрать?'),[fr('Un vieux stylo','э(н) вьё стило́'),fr('Un stylo bleu','э(н) стило блё́'),fr('Un nouveau stylo','э(н) нуво стило́')],0,'В записи указан старый предмет.','Нужен признак «старая»; синий цвет не задаёт этот признак, а новая ручка означает другое.')])

s=start(1,'Различайте большой и маленький размер знакомой вещи. Выбирайте размер по подписи и ставьте его в показанное место перед названием.',['grand','petit','rouge','bleu','vert','sac','livre','cest-identify','sil-vous-plait'])
listen(s,['PRE_A1.U07.UNDERSTAND'],['sac','rouge','bleu','vert'],['rouge'],'Вспомните цвета: какой цвет сумки назвали?','Un sac rouge.','э(н) сак ру́ж.',['Синий','Красный','Зелёный'],1,'Назван красный цвет сумки.','Сумка красная; синий и зелёный в реплике не названы.')
intro(s,2,'Два признака размера вещи: grand — большой, petit — маленький. В показанных сочетаниях они стоят перед названием: un grand sac — «большая сумка», un petit sac — «маленькая сумка». Это отличается от знакомого цвета после названия.',['grand','petit'],[('grand','гра́(н)'),('petit','пёти́'),('un grand sac','э(н) гра(н) са́к'),('un petit sac','э(н) пёти са́к')],('Un grand sac. Un petit sac.','э(н) гра(н) са́к. э(н) пёти са́к.'))
pairs(s,[U],[('grand','Большой'),('petit','Маленький'),('rouge','Красный')],'Два слова называют размер, одно — знакомый цвет.','Различайте большой и маленький размер; красный — признак цвета, а не размера.')
listen(s,[U],['sac','grand','petit'],['petit'],'Какой признак размера назван у сумки?','Un petit sac.','э(н) пёти са́к.',['Большой','Размер не назван','Маленький'],2,'Назван маленький размер сумки.','Сумка маленькая; её размер прямо указан.')
choose(s,'vocabulary',[A],['sac','grand','petit','rouge'],['grand'],'Нужна сумка большого размера. В какой записи размер указан прямо?',ru('Не заменяйте размер цветом.'),[fr('Un sac rouge','э(н) сак ру́ж'),fr('Un grand sac','э(н) гра(н) са́к'),fr('Un petit sac','э(н) пёти са́к')],1,'В записи прямо указан большой размер сумки.','Нужен большой размер; маленький не подходит, а красный цвет размер не сообщает.')
choose(s,'reading',[A],['sac','livre','grand','petit'],['livre','petit'],'Какой размер указан у книги в списке?',fr('Un grand sac. Un petit livre.','э(н) гра(н) са́к. э(н) пёти ли́вр.'),['Большой','Маленький','Размер книги не указан'],1,'Книга маленькая; большой размер относится к сумке.','Нужно выбрать маленький размер книги и не переносить признак другой вещи.')
fill(s,[A],['sac','grand','petit','sil-vous-plait'],['grand'],'Попросите большую сумку. Выберите размер для показанного сочетания.','Un ','э́(н)',' sac, s’il vous plaît.','сак, силь ву плэ́',[wc('petit'),wc('grand')],1,'Un grand sac, s’il vous plaît.','э(н) гра(н) сак, силь ву плэ́.','В просьбе указан большой размер.','Нужен большой размер; маленький изменит требуемую вещь.')
order(s,[A],['cest-identify','sac','petit'],[],'Соберите «Это маленькая сумка» по показанному образцу: размер перед названием вещи.',[('C’est','сэ'),('un','э́(н)'),('petit','пёти́'),('sac.','са́к')],'C’est un petit sac.','сэт э(н) пёти са́к.','Признак размера поставлен перед названием сумки.','Начните с указания, затем поставьте артикль, размер и название в показанном порядке.')
page(s,[('Размер в коротком сочетании',['Здесь большой и маленький относятся к размеру вещи. Не выводите размер из цвета и не переносите эти значения на рост человека.'],[W['grand']['example'],W['petit']['example']]),('Порядок учим по образцу',['Два показанных признака размера стоят перед названием. Знакомый цвет ставился после названия: положение одного типа признака не задаёт порядок для всех прилагательных.'],[ex('Un petit sac.','Маленькая сумка.','э(н) пёти са́к'),ex('Un sac rouge.','Красная сумка.','э(н) сак ру́ж')]),('Предметы в списке различаются',['Размер относится к конкретной записи. У одной вещи он может быть большим, у другой — маленьким; для ответа найдите именно запрошенный предмет.'],[ex('Un grand sac. Un petit livre.','Большая сумка. Маленькая книга.','э(н) гра(н) сак. э(н) пёти ли́вр.')])])

s=start(2,'Различайте длинный и короткий предмет по подписи и звучанию. Не смешивайте длину с общим размером; собирайте показанный образец с ручкой.',['grand','petit','long','court','sac','stylo','sil-vous-plait'])
choose(s,'reading',[U],['sac','grand','petit'],['grand'],'Какой размер сумки указан в знакомом сочетании?',fr('Un grand sac.','э(н) гра(н) са́к.'),['Маленький','Большой','Размер не указан'],1,'Указан большой размер.','Сумка большая; маленький размер этой записью не назван.')
intro(s,2,'Два признака длины: long — длинный, court — короткий. В наших подписях используем образцы un stylo long — «длинная ручка», un stylo court — «короткая ручка». Здесь название ручки стоит перед признаком длины. Это готовые образцы, а не правило порядка всех прилагательных.',['long','court'],[('long','ло́(н)'),('court','ку́р'),('un stylo long','э(н) стило ло́(н)'),('un stylo court','э(н) стило ку́р')],('Un stylo long. Un stylo court.','э(н) стило ло́(н). э(н) стило ку́р.'))
