page(s,[('Длина — отдельный признак',['Длинный и короткий относятся к длине. Большой и маленький не сообщают ту же информацию автоматически; опирайтесь на точное слово в подписи.'],[W['long']['example'],W['court']['example']]),('Показанный порядок в подписях',['С ручкой здесь используем названный предмет и признак после него. В сборке требуется воспроизвести именно этот образец; универсальный порядок всех прилагательных не вводится.'],[ex('Un stylo long.','Длинная ручка.','э(н) стило ло́(н)'),ex('Un stylo court.','Короткая ручка.','э(н) стило ку́р')]),('Короткая просьба',['Добавьте знакомую формулу вежливости после названия нужного предмета с признаком. Дополнительный глагол для этого упражнения не нужен.'],[ex('Un stylo court, s’il vous plaît.','Короткую ручку, пожалуйста.','э(н) стило кур, силь ву плэ́')])])

